import sys
sys.path.insert(0,'/opt/tools')
import rcb_dtb as r, numpy as np, mujoco
from scipy.spatial.transform import Rotation as R
from PIL import Image
np.set_printoptions(precision=4,suppress=True)
class Controller:
 def __init__(self):
  self.s=r.Session();self.m=self.s.model;self.d=self.s.data;self.k=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,rot,q=None):
  q=self.s.targets.copy() if q is None else q.copy(); self.k.qpos[:]=self.d.qpos
  for i in range(150):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   ep=p-self.k.xpos[self.bid];er=R.from_matrix(rot@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()
   e=np.r_[ep,er];
   if np.linalg.norm(e)<1e-5:break
   jp=np.zeros((3,self.m.nv));jr=jp.copy();mujoco.mj_jacBody(self.m,self.k,jp,jr,self.bid)
   J=np.r_[jp[:,:7],jr[:,:7]];dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]+=dq*min(1,.12/max(np.max(np.abs(dq)),1e-8));q=np.clip(q,self.s.lower+.001,self.s.upper-.001)
  return q
 def move(self,p,rot,hand=None,n=120):
  p0,r0=self.pose();rv=R.from_matrix(rot@r0.T).as_rotvec();h0=self.s.targets[7:].copy()
  for i in range(n):
   t=(i+1)/n;t=t*t*(3-2*t)
   q=self.ik(p0+(p-p0)*t,R.from_rotvec(rv*t).as_matrix()@r0)
   if hand is not None:q[7:]=h0+(hand-h0)*t
   self.s.step(q)
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.s.targets)
 def snap(self,label):
  for cam in ['front','side','top']:Image.fromarray(self.s.render(cam)).resize((960,720)).save('/app/output/'+label+'_'+cam+'.png')
 def contacts(self):
  for c in self.d.contact:
   if self.s._obj in self.m.geom_bodyid[[c.geom1,c.geom2]]:
    print(self.m.geom(c.geom1).name,self.m.geom(c.geom2).name,round(c.dist,4))
def hand(a=1):
 return np.array([1.2,0,0.4,0,0.5]+[a,0,a,0.5]*3+[0,a,0,a,0.5])
if __name__=='__main__':
 c=Controller();s=c.s;p,rot=c.pose()
 for a in [0,.5,1,1.5]:
  s.data.qpos[s._jq[7:]]=hand(a);mujoco.mj_forward(c.m,c.d)
  print('a=',a)
  for f in ['thumb','index','middle','ring','pinky']:
   b=c.m.body('palmleft_'+f+'_DP').id;pad=c.d.xpos[b]+c.d.xmat[b].reshape(3,3)@np.array([.016,-.008,0]);print(f,rot.T@(pad-p))
PY
